def sort_numbers(numbers: str) -> str:
    # Define a dictionary mapping number words to their numeric values
    num_dict = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Split the input string into individual number words
    number_words = numbers.split()

    # Sort the list of number words based on their numeric value
    sorted_number_words = sorted(number_words, key=lambda word: num_dict[word])

    # Join the sorted number words back into a single string
    return ' '.join(sorted_number_words)

