from typing import List

def triples_sum_to_zero(l: List[int]) -> bool:
    l.sort()  # Sort the list to make it easier to find triplets
    n = len(l)

    for i in range(n-2):  # Iterate through the list up to the third last element
        left, right = i + 1, n - 1

        while left < right:
            current_sum = l[i] + l[left] + l[right]

            if current_sum == 0:
                return True  # Found a triplet that sums to zero
            elif current_sum < 0:
                left += 1  # Move the left pointer to the right
            else:
                right -= 1  # Move the right pointer to the left

    return False  # No triplet found that sums to zero

def change_base(x: int, base: int) -> str:
    if base < 2 or base > 9:
        raise ValueError("Base must be between 2 and 9.")

    result = ""
    while x > 0:
        remainder = x % base
        result = str(remainder) + result
        x //= base

    return result

