def total_match(lst1: List[str], lst2: List[str]) -> List[str]:
    # Calculate the total number of characters in each list
    char_count_lst1 = sum(len(s) for s in lst1)
    char_count_lst2 = sum(len(s) for s in lst2)

    # Compare the total character counts and return the appropriate list
    if char_count_lst1 < char_count_lst2:
        return lst1
    elif char_count_lst1 > char_count_lst2:
        return lst2
    else:
        return lst1

