def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1
    else:
        # For n > 1, there are two cases to consider:
        # 1. The number starts with 1 and ends with any digit (except 0).
        # 2. The number ends with 1 and starts with any digit (except 0).
        # Since each case has 9 options for the middle digits, we multiply by 9^2.
        return 9 * 9**(n-2)

