from typing import List

def unique_digits(x: List[int]) -> List[int]:
    def has_even_digit(n):
        while n > 0:
            if n % 2 == 0:
                return True
            n //= 10
        return False

    return sorted(set(filter(lambda num: not has_even_digit(num), x)))

