from typing import List

def move_one_ball(arr: List[int]) -> bool:
    # Check if the array is already sorted or empty
    if arr == sorted(arr) or len(arr) == 0:
        return True

    # Count the number of shifts needed to sort the array
    shifts = 0
    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            shifts += 1

    # Perform the right shift operation as many times as needed
    while shifts > 0:
        arr.append(arr.pop(0))
        shifts -= 1

    # Check if the array is now sorted
    return arr == sorted(arr)

# Test cases
