def prod_signs(arr: List[int]) -> Optional[int]:
    if not arr:
        return None

    # Calculate the product of all signs
    sign_product = 1
    for num in arr:
        if num == 0:
            return 0
        elif num < 0:
            sign_product *= -1

    # Calculate the sum of magnitudes multiplied by the product of signs
    total_sum = sum(abs(num) * sign_product for num in arr)

    return total_sum

