def next_smallest_palindrome(n):
    # Convert the number to string for easy manipulation
    num_str = str(n)

    # Find the length of the number
    length = len(num_str)

    # If the number is already a palindrome, increment the last digit and check if it's still a palindrome
    if num_str == num_str[::-1]:
        n += 1
        while not num_str == num_str[::-1]:
            n += 1
            num_str = str(n)
    else:
        # If the number is not a palindrome, find the first non-palindromic digit from the right
        for i in range(length - 1, -1, -1):
            if num_str[i] != '9':
                break

        # Increment the found digit by one and adjust the rest of the digits to form the next palindrome
        num_str = num_str[:i+1] + str(int(num_str[i]) + 1) + '0' * (length - i - 2)

    return int(num_str)

