    elif m > n or m < 0:
        raise ValueError("Invalid input values. m must be less than or equal to n.")

    # Recursive case: sum of Eulerian numbers for (n-1, m) and (n-1, m-1)
    return eulerian_num(n-1, m) + (m * eulerian_num(n-1, m-1))

