def amicable_numbers_sum(n):
    def is_amicable(a, b):
        return sum(divisors(a)) == b and sum(divisors(b)) == a

    divisors = lambda x: [i for i in range(1, x) if x % i == 0]
    amicable_pairs = [(a, b) for a in range(1, n+1) for b in range(a+1, n+1) if is_amicable(a, b)]
    return sum(x + y for x, y in amicable_pairs)

def amicable_numbers_sum(n):
    def get_divisors(x):
        divisors = []
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                divisors.append(i)
                if i != x // i:
                    divisors.append(x // i)
        return divisors

    amicable_pairs = []

    for a in range(1, n+1):
        divs_a = get_divisors(a)
        divs_b = get_divisors(sum(divs_a))

        if len(divs_b) > 0 and sum(divs_b) == a:
            amicable_pairs.append((a, sum(divs_a)))

    return sum(x + y for x, y in amicable_pairs)

