def max_Abs_Diff(arr):
    # Initialize the minimum and maximum values with the first element of the array
    min_val = arr[0]
    max_val = arr[0]

    # Iterate through the array starting from the second element
    for i in range(1, len(arr)):
        # Update the minimum value if the current element is smaller
        if arr[i] < min_val:
            min_val = arr[i]
        # Update the maximum value if the current element is larger
        elif arr[i] > max_val:
            max_val = arr[i]

    # Calculate the absolute difference between the maximum and minimum values
    return abs(max_val - min_val)

