def next_Perfect_Square(n):
    # Calculate the square root of n and round it down to the nearest integer
    sqrt_n = math.floor(math.sqrt(n))
    # Check if sqrt_n is an integer
    if sqrt_n * sqrt_n == n:
        # If sqrt_n is an integer, return its square
        return sqrt_n * sqrt_n
    else:
        # If sqrt_n is not an integer, calculate the next perfect square by adding 1 to sqrt_n
        return (sqrt_n + 1) * (sqrt_n + 1)

