    n = len(arr)
    # Initialize dp arrays for increasing and decreasing subsequences
    inc = [1] * n
    dec = [1] * n

    # Fill in the dp arrays
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum sum of bitonic subsequences
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - 1)

    return max_sum

