        if p < 2:
            return False
        if p == 2 or p == 3:
            return True
        if p % 2 == 0 or p % 3 == 0:
            return False
        i = 5
        while i * i <= p:
            if p % i == 0 or p % (i + 2) == 0:
                return False
            i += 6
        return True

