def max_aggregate(tuples_list):
    # Initialize an empty dictionary to store names and their highest scores
    name_scores = {}

    # Iterate through each tuple in the list
    for name, score in tuples_list:
        # If the name is already in the dictionary, update its score if the current one is higher
        if name in name_scores:
            if score > name_scores[name]:
                name_scores[name] = score
        else:
            # Otherwise, add the name and its score to the dictionary
            name_scores[name] = score

    # Find the name with the highest score
    max_name = max(name_scores, key=name_scores.get)
    max_score = name_scores[max_name]

    return (max_name, max_score)

