def get_max_sum(n):
    # Base case: if n is less than or equal to 5, return n itself
    if n <= 5:
        return n

    # Initialize variables to store the maximum sums for different divisions of n
    max_sum_2 = max_sum_3 = max_sum_4 = max_sum_5 = 0

    # Calculate the maximum sums for dividing n by 2, 3, 4, and 5
    if n % 2 == 0:
        max_sum_2 = get_max_sum(n // 2)
    if n % 3 == 0:
        max_sum_3 = get_max_sum(n // 3)
    if n % 4 == 0:
        max_sum_4 = get_max_sum(n // 4)
    if n % 5 == 0:
        max_sum_5 = get_max_sum(n // 5)

    # Return the maximum sum among all possible divisions
    return max(max_sum_2, max_sum_3, max_sum_4, max_sum_5)

