def cal_sum(n):
    # Initialize the first three Perrin numbers
    p = [3, 0, 2]

    # Calculate the next Perrin number and add it to the list
    for i in range(3, n + 1):
        p.append(p[i - 2] + p[i - 3])

    # Return the sum of all Perrin numbers up to n
    return sum(p)

def sumofFactors(n):
    # Initialize sum to 0
    sum = 0

    # Iterate through all numbers from 1 to n
    for i in range(1, n + 1):
        # Check if i is a factor of n
        if n % i == 0:
            # If i is even, add it to the sum
            if i % 2 == 0:
                sum += i

    return sum

