def find_kth(arr1, arr2, k):
    # Initialize pointers for both arrays
    i = j = 0

    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            k -= 1
            if k == 0:
                return arr1[i]
            i += 1
        else:
            k -= 1
            if k == 0:
                return arr2[j]
            j += 1

    # If one array is exhausted, return the remaining elements of the other array
    if i < len(arr1):
        while k > 0:
            k -= 1
            i += 1
        return arr1[i]

    while k > 0:
        k -= 1
