        seen.add(char)
    return None

def prime_num(n):
    # Check if n is less than 2, which are not prime numbers
    if n < 2:
        return False
    # Check for factors from 2 up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    # If no factors were found, n is a prime number
    return True

