def get_pairs_count(arr, sum):
    # Initialize a dictionary to store the frequency of each element in the array
    freq = {}

    # Count the frequency of each element in the array
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize a counter to store the number of valid pairs
    count = 0

    # Iterate through the array again
    for num in arr:
        # Check if the complement (sum - num) exists in the dictionary
        if sum - num in freq:
            # If it does, add the minimum of the frequencies of num and sum - num to the count
            count += min(freq[num], freq[sum - num])

    return count

