def check_integer(text):
    # 去除字符串两端的空白字符
    text = text.strip()

    # 检查字符串长度是否小于1
    if len(text) < 1:
        return None

    # 如果字符串的第一个字符是 '+' 或 '-'，去掉第一个字符
    if text[0] in '+-':
        text = text[1:]

    # 检查剩余部分是否只包含数字
    return text.isdigit()

def div_sum(num):
    res = 1
    i = 2
    while i * i <= num:
        if num % i == 0:
            res += i
            if i * i != num:
                res += num // i
        i += 1
    return res

def amicable_numbers_sum(limit):
    amicables = set()
    for num in range(limit + 1, 2):
        if num in amicables:
            continue
        sum_fact = div_sum(num)
        sum_fact2 = div_sum(sum_fact)
        if num == sum_fact2 and num != sum_fact:
            amicables.add(num)
            amicables.add(sum_fact2)
    return sum(amicables)

