def find_length(string):
    current_zero_count = 0
    current_one_count = 0
    max_diff = 0

    for c in string:
        if c == '0':
            current_zero_count += 1
        else:
            current_one_count += 1

        # 更新最大差值
        max_diff = max(max_diff, abs(current_zero_count - current_one_count))

    return max_diff

