import math

def sum(a, b):
    sum = 0
    n = math.gcd(a, b)
    N = int(math.sqrt(n))
    for i in range(1, N + 1):
        if n % i == 0:
            sum += i
            if i != n // i:
                sum += n // i
    return sum

