    s = sum(my_matrix[0])
    if any((sum(row) != s for row in my_matrix)):
        return False
    if sum((my_matrix[i][i] for i in range(len(my_matrix)))) != s:
        return False
    if sum((my_matrix[i][len(my_matrix) - i - 1] for i in range(len(my_matrix)))) != s:
        return False
    # Check the center element
    if len(my_matrix) % 2 == 0 and my_matrix[len(my_matrix) // 2][len(my_matrix) // 2] != s:
        return False
    return True

