def find_solution(a, b, n):
    i = 0
    while i * a <= n:
        if (n - i * a) % b == 0:
            return (i, (n - i * a) // b)
        i = i + 1
    return None

def sum_series(n):
    if n < 0:
        return 0
    total_sum = 0
    for i in range(n // 2 + 1):
        total_sum += (n - 2 * i)
    return total_sum

