def get_total_number_of_sequences(m, n):
    T = [[0 for _ in range(n + 1)] for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                T[i][j] = 0
            elif i > j:
                T[i][j] = 0
            elif j == 1:
                T[i][j] = i
            else:
                # 修改递归关系以满足新的约束条件
                T[i][j] = T[i - 1][j] + T[(i // 2) if i % 2 == 0 else i // 2 + 1][j - 1]
    return T[m][n]

