def is_palindrome(s):
    return s == s[::-1]

def lps(str1):
    n = len(str1)
    dp = [[0] * n for _ in range(n)]

    # Initialize the first row and column
    for i in range(n):
        dp[i][0] = 1
        dp[0][i] = 1

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, n):
            if str1[i-1] == str1[j-1] and is_palindrome(str1[i-1:j]):
                dp[i][j] = dp[i-1][j-1] + 2
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[n-1][n-1]

