def max_sum_increasing_subseq(a, n, index, k):
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Initialize the first row
    for i in range(n):
        if a[i] >= a[0]:
            dp[0][i] = a[i] + a[0]
        else:
            dp[0][i] = a[i]

    # Fill the dp table
    for i in range(1, n):
        for j in range(i + 1, n):
            if a[j] > a[i] and j > i:
                if dp[i - 1][i] + a[j] > dp[i - 1][j]:
                    dp[i][j] = dp[i - 1][i] + a[j]
                else:
                    dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    # Return the result for the specified index and k
    return dp[index][k]

