def set_left_most_unset_bit(n):
    # 如果 n 是 0，则直接返回 1
    if n == 0:
        return 1

    # 找到最左边的未设置位
    pos = 0
    while n & 1:
        pos += 1
        n >>= 1

    # 确保 pos 不超过 31
    if pos > 31:
        raise ValueError("Input is too large for this implementation")

    # 返回结果，即 n | (1 << pos)
    return n | (1 << pos)

