def max_Product(arr):
    # 检查数组是否为空或只有一个元素
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements")

    # 找到数组中的最大值和最小值
    max_val = max(arr)
    min_val = min(arr)

    # 如果数组中有负数，则找出最大的负数
    if any(x < 0 for x in arr):
        neg_max = max(val for val in arr if val < 0)

        # 返回最大的两个数的乘积
        return max(neg_max * max_val, max_val * min_val)
    else:
        # 如果数组中没有负数，则直接返回最大的两个数的乘积
        return max_val * min_val

