import math

def sumofFactors(n):
    if n % 2 != 0:
        return 0
    total = 1  # Start with 1 because it's always a factor
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i == n // i:
                total += i
            else:
                total += i + n // i
    return total

# 测试用例
assert sumofFactors(18) == 26
assert sumofFactors(30) == 48
assert sumofFactors(6) == 8

