from typing import List

def max_product(arr: List[int]) -> int:
    if not arr:
        return 0

    # Initialize variables to store the maximum and minimum products ending at each index
    max_ending = min_ending = arr[0]

    # Initialize the result variable to store the maximum product found so far
    result = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > max_ending:
            max_ending, min_ending = arr[i], max_ending // arr[i]
        elif arr[i] < min_ending:
            max_ending, min_ending = min_ending * arr[i], arr[i]
        else:
            max_ending, min_ending = arr[i], arr[i]

        # Update the result with the maximum product found so far
        result = max(result, max_ending)

    return result

