from functools import reduce

def find_remainder(arr, n):
    return reduce(lambda x, y: x * y, arr) % n

def check_Consecutive(l):
    # 检查列表是否为空或只有一个元素
    if len(l) <= 1:
        return True

    # 对列表进行排序
    l.sort()

    # 检查排序后的列表是否连续
    for i in range(1, len(l)):
        if l[i] != l[i-1] + 1:
            return False

    return True

