def max_sub_array_sum(a, size):
    max_so_far = 0
    max_ending_here = 0
    for i in range(size):
        max_ending_here = max_ending_here + a[i]
        if max_ending_here < 0:
            max_ending_here = 0
        elif max_so_far < max_ending_here:
            max_so_far = max_ending_here
    return max_so_far

def count_Pairs(arr, n):
    cnt = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] != arr[j]:
                cnt += 1
    return cnt

