from collections import Counter

def get_pairs_count(arr, sum_):
    cnt = 0
    num_counts = Counter(arr)

    for n in num_counts:
        complement = sum_ - n
        if complement in num_counts:
            # If the complement is the same as n, we need to subtract one pair
            if complement == n:
                cnt += num_counts[n] // 2
            else:
                cnt += min(num_counts[n], num_counts[complement])

    return cnt

