from collections import deque

def check_expression(exp):
    if len(exp) == 0 or len(exp) % 2 == 1:
        return False
    stack = deque()
    for ch in exp:
        if ch == '(' or ch == '{' or ch == '[':
            stack.append(ch)
        elif ch == ')':
            if not stack or stack.pop() != '(':
                return False
        elif ch == '}':
            if not stack or stack.pop() != '{':
                return False
        elif ch == ']':
            if not stack or stack.pop() != '[':
                return False
    return not stack

