def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def factorize(n: int) -> List[int]:
    factors = []
    # Check for divisibility by 2 first
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Now check odd numbers starting from 3
    for i in range(3, int(sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i

    # If n is a prime number greater than 2
    if n > 2 and is_prime(n):
        factors.append(n)

    return factors

