    def newton_raphson(f: Callable[[float], float], df: Callable[[float], float], initial_guess: float) -> float:
        while True:
            next_guess = initial_guess - f(initial_guess) / df(initial_guess)
            if abs(next_guess - initial_guess) < 1e-6:
                break
            initial_guess = next_guess
        return next_guess

    def solve_for_root():
        first_derivative = derivative(xs)
        second_derivative = derivative(first_derivative)

        # Find the root using Newton-Raphson method
        return newton_raphson(lambda x: poly(xs, x), lambda x: first_derivative(xs)[0] * poly(xs, x) - poly(xs, x), 1.0)

    return solve_for_root()

