def rotate_letter(letter, n):
    if letter.isupper():
        return chr((ord(letter) - ord('A') + n * 2) % 26 + ord('A'))
    else:
        return chr((ord(letter) - ord('a') + n * 2) % 26 + ord('a'))

def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            result += rotate_letter(char.lower(), 2)
        else:
            result += char
    return result.upper()

