    """ Return a list of size n where the value of the element at index i is the factorial of i if i is even
    or the sum of numbers from 1 to i otherwise. """
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_i(i))
    return result

