from typing import List

def max_fill(grid: List[List[int]], capacity: int) -> int:
    rows = len(grid)
    cols = len(grid[0])

    def calculate_water(well_index):
        return sum(row[well_index] for row in grid)

    def fill_bucket(bucket_index, current_water):
        if current_water == 0:
            return 0

        filled_wells = []

        for i in range(rows):
            if grid[i][bucket_index]:
                filled_wells.append(i)

        total_steps = 0

        while current_water > 0:
            for well in filled_wells:
                grid[well][bucket_index] = 0

                # Calculate how much more water we can add
                remaining_water = min(current_water, capacity - calculate_water(filled_wells))

                # Fill the bucket with the remaining water
                current_water -= remaining_water

                total_steps += 1

            filled_wells.clear()

        return total_steps

    steps = 0
    for well_index in range(cols):
        steps += fill_bucket(0, calculate_water(well_index))

    return steps

