def prod_signs(arr: List[int]) -> int | None:
    if not arr:
        return None

    sign_product = 1
    magnitude_sum = 0

    for num in arr:
        if num == 0:
            return 0
        elif num < 0:
            sign_product *= -1
        else:
            sign_product *= 1

        magnitude_sum += abs(num)

    return magnitude_sum * sign_product

from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dp = [[float('inf')] * n for _ in range(n)]

    # Initialize the first row and column
    for i in range(n):
        dp[0][i] = grid[0][i]
        dp[i][0] = grid[i][0]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # Find the shortest path of length k
    for i in range(k+1):
        for j in range(k-i+1):
            dp[k][k-j] = min(dp[k][k-j], dp[j][k-j])

    return dp[-1][-1]

