def is_equal_to_sum_even(n):
    # Check if n is less than 8, since the smallest sum of four even numbers is 2+2+2+2=8
    if n < 8:
        return False

    # If n is divisible by 4, it can be expressed as the sum of four even numbers (e.g., 4 + 4 + 2 + 2)
    if n % 4 == 0:
        return True

    # Otherwise, check if n - 2 is divisible by 4. This would mean that n itself can be expressed as the sum of four even numbers.
    return (n - 2) % 4 == 0

