from functools import cmp_to_key

def order_by_points(nums: List[int]) -> List[int]:
    def compare(a: int, b: int) -> int:
        sa = abs(sum(int(c) for c in str(a)))
        sb = abs(sum(int(c) for c in str(b)))

        if sa < sb:
            return -1
        elif sa > sb:
            return 1
        else:
