def bf(planet1, planet2):
    # Define the order of planets from closest to farthest from the Sun
    PLANETS = {"Mercury": 0, "Venus": 1, "Earth": 2, "Mars": 3, "Jupiter": 4,
               "Saturn": 5, "Uranus": 6, "Neptune": 7}

    # Check if both inputs are valid planet names
    if planet1 not in PLANETS or planet2 not in PLANETS:
        return ()

    # Find the index positions of the input planets
    idx_planet1 = PLANETS[planet1]
    idx_planet2 = PLANETS[planet2]

    # Return the planets between the two given planets (inclusive)
    return tuple(PLANETS[k] for k in range(idx_planet1 + 1, idx_planet2))

# Example usage
print(bf("Jupiter", "Neptune"))  # Output: ('Saturn', 'Uranus')
print(bf("Earth", "Mercury"))    # Output: ('Venus')
print(bf("Mercury", "Uranus"))   # Output: ('Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn')

import math

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    """Return x if n is prime, else return y."""
    if is_prime(n):
        return x
    else:
        return y

