def is_Monotonic(array):
    # Check if the array is monotonically increasing
    if all(array[i] <= array[i + 1] for i in range(len(array) - 1)):
        return True

    # Check if the array is monotonically decreasing
    elif all(array[i] >= array[i + 1] for i in range(len(array) - 1)):
        return True

    else:
        return False

