def sequence(n):
    if n <= 0:
        return None
    elif n == 1 or n == 2:
        return n - 1
    else:
        # Initialize the first two numbers of the sequence
        a, b = 1, 1
        for _ in range(3, n + 1):
            a, b = b, a + b
        return b

# Example usage
print(sequence(10))  # Output: 6
print(sequence(2))   # Output: 1
print(sequence(3))   # Output: 2

def memoize(f):
    cache = {}
    def helper(x):
        if x not in cache:
            cache[x] = f(x)
        return cache[x]
    return helper

@memoize
def sequence(n):
    if n <= 0:
        return None
    elif n == 1 or n == 2:
        return n - 1

    # Initialize the first two numbers of the sequence
    a, b = 1, 1
    result = []

    for i in range(3, n + 1):
        result.append(b)
        a, b = b, a + b

    return result[-1]

# Example usage
print(sequence(10))  # Output: 6
print(sequence(2))   # Output: 1
print(sequence(3))   # Output: 2

