def next_smallest_palindrome(n):
    """
    Find the next smallest palindrome of n.

    Parameters:
    n (int): The number to find the next smallest palindrome for.

    Returns:
    int: The next smallest palindrome after n.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    def next_palindrome(num):
        num_str = str(num)
        length = len(num_str)

        # If the number is already a palindrome, increment by one digit
        if is_palindrome(num):
            return num + 1

        # Try to make the left half of the number into a palindrome
        for i in range(length // 2):
            if num_str[i] != num_str[length - i - 1]:
                new_num_str = num_str[:i+1][::-1] + num_str[i+1:]
                return int(new_num_str)

        # If no valid palindrome can be made, try increasing the last digit
        for i in range(length):
            if is_palindrome(int(str(num).zfill(i))):
                return int(str(num).zfill(i))

    return next_palindrome(n)


