import math

def factorial(n):
    """Calculate factorial of n."""
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def comb(n, k):
    """Calculate combination C(n, k)."""
    return factorial(n) // (factorial(k) * factorial(n-k))

def eulerian_num(n, m):
    """
    Calculate the nth Eulerian number A(n, m).

    Args:
    n (int): The order of the Eulerian number.
    m (int): The size of the set.

    Returns:
    int: The value of the Eulerian number A(n, m).
    """
    if m < n or m > n + 1:
        return 0

    # Base cases for small values of n and m
    if n == 0:
        return 1
    elif m == 1:
        return 1
    elif m == 2:
        return 2 * n - 1

    # Recursive calculation using Pascal's triangle properties
    result = 0
    for k in range(m):
        result += comb(m - 1, k) * (-1)**k * eulerian_num(n - 1, k)
    return result

