    all_rotations = set()
    for _ in range(rotations):
        all_rotations.update(generate_rotations(binary_string))

    count = 0
    for rotation in all_rotations:
        if int(rotation, 2) % 2 == len(rotation) % 2:
            count += 1

    return count

