def search(nums):
    left = 0
    right = len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        if nums[mid] > nums[right]:
            # The target is in the left half of the array.
            right = mid
        else:
            # The target is in the right half of the array.
            left = mid + 1

    return nums[left]

def is_amicable(n):
    """
    Check if two numbers are amicable.
    """
    def get_divisors(num):
        divisors = set()
        for i in range(1, int(num ** 0.5) + 1):
            if num % i == 0:
                divisors.add(i)
                divisors.add(num // i)
        return divisors

    divisor_set_a = get_divisors(n)
    divisor_set_b = get_divisors(sum(divisor_set_a))

    # If the sets have different sizes or one of them contains n itself,
    # then they are not amicable.
    return len(divisor_set_a) != len(divisor_set_b) and n not in divisor_set_a

def amicable_numbers_sum(limit):
    total_sum = 0
    for num in range(1, limit+1):
        if is_amicable(num):
            total_sum += num
    return total_sum

