        return False

    # Initialize variables for binary search and result flag.
    left = 0
    right = n.bit_length() - 1
    found = False

    while left <= right:
        mid = (left + right) // 2
        power_of_two = 1 << mid

        if power_of_two > n:
            right = mid - 1
        elif power_of_two == n:
            return True
        else:
            left = mid + 1

    return False

def is_Sum_Of_Powers_Of_Two(n):
    # Check if n is less than 1, return False immediately.
    if n < 1:
        return False

    # Convert the number to its binary representation without leading zeros.
    binary_representation = bin(n)[2:]

    # Count the number of '1's in the binary representation.
    ones_count = binary_representation.count('1')

    # If there are no '1's, it means the number cannot be expressed as a sum of non-zero powers of two.
    if ones_count == 0:
        return False

    # If there is at least one '1', then the number itself is a power of two.
    if ones_count == 1:
        return True

    # If there are more than one '1', check if they are consecutive.
    if ones_count > 1:
        for i in range(len(binary_representation)):
            if binary_representation[i] == '1':
                if i + 1 < len(binary_representation) and binary_representation[i+1] == '1':
                    continue
                else:
                    return False
        return True

    return False

