        """Flip the first 'start' elements in the array."""
        for i in range(start // 2):
            arr[i], arr[start - i - 1] = arr[start - i - 1], arr[i]

    n = len(arr)
    while n > 0:
        # Find the index of the maximum element in the unsorted portion.
        max_index = n - 1
        for i in range(n - 1, 0, -1):
            if arr[i] > arr[max_index]:
                max_index = i

        # Move the maximum element to its correct position.
        if max_index != 0:
            flip(max_index)

        # Place the maximum element at the end of the sorted portion.
        flip(max_index + 1)

        n -= 1

    return arr

