def max_sum(arr):
    n = len(arr)

    # Initialize variables to store the maximum sums
    inc = [0] * n
    dec = [0] * n

    # Calculate the maximum sum of increasing subsequences ending at each index
    for i in range(n):
        inc[i] = arr[i]

        # Find the maximum sum of increasing subsequences starting from this point
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Calculate the maximum sum of decreasing subsequences starting from each index
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]

        # Find the maximum sum of decreasing subsequences ending at this point
        for j in range(i+1, n):
            if arr[j] > arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # The answer will be the sum of the maximums found above
    return max(max(inc), max(dec))

