def list_split(lst, n):
    # Split the list into chunks of size n
    return [lst[i:i+n] for i in range(0, len(lst), n)]

def dict_filter(dictionary, threshold):
    # Filter the dictionary for items where value is greater than or equal to the threshold
    filtered_dict = {key: value for key, value in dictionary.items() if value >= threshold}
    return filtered_dict

