    freq_dict = {}

    for digit in n_str:
        if digit in freq_dict:
            freq_dict[digit] += 1
        else:
            freq_dict[digit] = 1

    # Check if the frequency of each digit is <= the digit itself
    return all(freq <= int(digit) for digit, freq in freq_dict.items())

