def max_sum_increasing_subseq(arr, n, k):
    # Initialize variables for dynamic programming
    dp = [arr[0]] * (n + 1)
    prev_index = [-1] * (n + 1)

    # Fill the DP array with the maximum sum up to each index
    for i in range(1, n + 1):
        for j in range(i - 1, -1, -1):
            if arr[i - 1] < arr[j]:
                if dp[i - 1] + arr[i - 1] > dp[i]:
                    dp[i] = dp[i - 1] + arr[i - 1]
                    prev_index[i] = j

    # Find the position of the k-th element
    target_index = find_kth_element(arr, n, k)

    # Reconstruct the sequence using the previous index information
    result = []
    while target_index != -1:
        result.append(target_index)
        target_index = prev_index[target_index]

    return dp[-1], result[::-1]

