def large_product(list1, list2, n):
    # Initialize variables to store the maximum product and its factors
    max_product = -float('inf')
    max_factors = []

    # Iterate through all possible combinations of elements from both lists
    for i in range(len(list1)):
        for j in range(len(list2)):
            # Calculate the product of the current combination
            product = list1[i] * list2[j]

            # Update the maximum product if the current product is larger
            if product > max_product:
                max_product = product
                max_factors = [list1[i], list2[j]]

    # If there are fewer than n factors found, return all found factors
    if len(max_factors) < n:
        return max_factors

    # Otherwise, return the first n factors
    else:
        return max_factors[:n]

