def set_left_most_unset_bit(n):
    # Find the first unset bit from the right (most significant)
    for i in range(len(bin(n)) - 2, -1, -1):  # Start from the least significant bit and go to the most significant
        if n & (1 << i) == 0:
            return n | (1 << i)

