def find_lucas(n):
    # Base cases for the first two Lucas numbers
    if n == 0:
        return 2
    elif n == 1:
        return 1

    # Initialize the first two Lucas numbers
    l, p = 2, 1

    # Calculate the nth Lucas number iteratively
    for _ in range(2, n + 1):
        l, p = p, l + p

    return l

