def get_max_sum(n):
    """
    Calculate the maximum sum of f(n) where f(n) is defined as:
    f(n) = max((f(n/2) + f(n/3) + f(n/4) + f(n/5)), n)

    :param n: Integer, input number.
    :return: Maximum sum possible.
    """
    dp = [-1] * (n + 1)
    dp[0] = 0

    def helper(current_n):
        if current_n < 0:
            return float('-inf')

        if dp[current_n] != -1:
            return dp[current_n]

        dp[current_n] = max(helper(current_n // 2) + helper(current_n // 3) + helper(current_n // 4) + helper(current_n // 5), current_n)

        return dp[current_n]

    return helper(n)

