def tuple_intersection(list_of_tuples):
    """
    Finds the intersection of tuples from a list of tuples, ignoring the order.

    Args:
    list_of_tuples: A list of tuples

    Returns:
    A set containing the common elements found in all tuples in the input list,
    regardless of their original order.
    """
    # Convert each tuple into a sorted list and then convert back to a tuple for comparison
    unique_elements = {tuple(sorted(tup)) for tup in list_of_tuples}
    return unique_elements

