    # Iterate through each element in list1
    for i in range(len(list1)):
        # If any element in list1 matches an element in list2 starting from index i
        if list1[i] == list2[0]:
            j = 0
            while j < len(list2) and i + j < len(list1) and list1[i+j] == list2[j]:
                j += 1
            # If all elements match, return True
            if j == len(list2):
                return True
    # If no matching subarray found, return False
    return False

