def diff_even_odd(nums):
    # Find the first even and first odd numbers in the list
    first_even = None
    first_odd = None

    for num in nums:
        if num % 2 == 0:
            if not first_even:
                first_even = num
            else:
                break
        elif num % 2 != 0:
            if not first_odd:
                first_odd = num
            else:
                break

    return abs(first_even - first_odd)

