def get_ludic(limit):
    """
    Generate all lucid numbers up to the limit.

    A lucid number is defined as a positive integer that has exactly two distinct prime factors,
    and both of these prime factors are less than or equal to the square root of the number.
    """
    lucids = []
    for num in range(2, limit + 1):
        factors = set()
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                factors.add(i)
                factors.add(num // i)
        if len(factors) == 2 and all(is_prime(factor) for factor in factors):
            lucids.append(num)
    return lucids

