def prime_num(n):
    # Check for negative numbers and zero
    if n <= 1:
        return False

    # Check for even numbers greater than two
    if n > 2 and n % 2 == 0:
        return False

    # Check for all odd divisors up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2

    return True

def bell_number(n):
    # Initialize the first row of the Bell triangle with n+1 elements, all set to 1.
    bell_triangle = [1] * (n + 1)

    # Fill in the rest of the rows using the recurrence relation.
    for i in range(1, n + 1):
        for j in range(i, -1, -1):
            if j > 0:
                bell_triangle[j] += bell_triangle[j - 1]

    return bell_triangle[-1]

