    def has_divisible_digit(number):
        digits = [int(d) for d in str(number)]
        return all(digit != 0 and number % digit == 0 for digit in digits)

    result = []
    for num in range(startnum, endnum + 1):
        if has_divisible_digit(num):
            result.append(num)
    return result

