def check_expression(expression):
    """
    Check if the given expression has matching and properly nested parentheses.

    Args:
        expression (str): The string containing the expression with parentheses.

    Returns:
        bool: True if the expression is balanced, False otherwise.
    """

    stack = []
    opening_brackets = {'(', '[', '{'}
    closing_brackets = {')', ']', '}'}

    for i, char in enumerate(expression):
        if char in opening_brackets:
            stack.append((i, char))
        elif char in closing_brackets:
            if len(stack) == 0:
                return False
            last_opening_index, _ = stack.pop()
            if opening_brackets.index(char) != last_opening_index:
                return False

    return len(stack) == 0

