def find_sum(lst):
    # Create a dictionary to count occurrences of each element
    counts = {}
    for num in lst:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    total_sum = 0
    # Sum up all numbers that appear only once
    for key, value in counts.items():
        if value == 1:
            total_sum += key

    return total_sum

