def triangle_area(a, h):
    """Given length of a side and height return area for a triangle.
    >>> triangle_area(5, 3)
    7.5
    """
    # Ensure inputs are positive integers to avoid division by zero and negative results
    if not (isinstance(a, int) and isinstance(h, int)):
        raise ValueError("Both sides must be integers")
    elif a <= 0 or h <= 0:
        return None  # Return None if either side is non-positive
    else:
        # Calculate the area using the formula: (base * height) / 2
        return (a * h) / 2

