def memoize(f):
    cache = {}

    def helper(x, y):
        if x not in cache:
            cache[x] = helper(y, x)
        if y not in cache:
            cache[y] = helper(x, y)
        return cache[x] + cache[y]

    return lambda *args: helper(args[0], args[1])

@memoize
def eulerian_num(n, m):
    if m > n or n == 0:
        return 0
    if m == 0:
        return 1
    return (n - m) * eulerian_num(n - 1, m - 1) + (m - 1) * eulerian_num(n - 1, m)

