def sum(a, b):
    sum = 0
    for i in range(1, int(math.sqrt(min(a, b))) + 1):
        if a % i == 0 and b % i == 0:
            sum += i
            if i * i != a and i * i != b:  # Avoid adding the square root twice
                sum += min(a // i, b // i)
    return sum

