def get_total_number_of_sequences(m, n):
    T = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        T[i][0] = 1

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if i <= j:
                T[i][j] = 0
            elif j == 1:
                T[i][j] = i
            else:
                T[i][j] = T[i - 1][j] + T[i // 2][j - 1]

    return T[m][n]

