def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def count_Primes_nums(n):
    primes_count = 0
    for num in range(2, n):
        if is_prime(num):
            primes_count += 1
    return primes_count

