def division_elements(test_tup1, test_tup2):
    # 检查除数是否为零
    if any(ele2 == 0 for ele1, ele2 in zip(test_tup1, test_tup2)):
        return None  # 或者可以选择其他处理方式，例如返回一个特殊的值或者空列表

    # 计算商而不考虑余数
    result = []
    for ele1, ele2 in zip(test_tup1, test_tup2):
        try:
            quotient = ele1 // ele2
            result.append(quotient)
        except ZeroDivisionError:
            result.append(None)  # 返回None表示除数为零
    return tuple(result)

