def max_sub_array_sum_repeated(a, n, k):
    # 初始化一个二维数组用于存储子数组的最大和
    dp = [[0] * len(a) for _ in range(len(a))]

    # 遍历所有可能的位置对 (i, j)
    for i in range(len(a)):
        for j in range(i, len(a)):
            if i == j:
                dp[i][j] = a[i]
            else:
                dp[i][j] = max(dp[i+1][j-1] + a[j], a[j])

    # 计算最大子数组和
    max_sum = float('-inf')
    for i in range(n):
        current_sum = 0
        for j in range(k):
            start_index = i * n + min(j, n - 1)
            end_index = i * n + min(j + 1, n - 1)
            if start_index >= len(a): 
                break
            current_sum += dp[start_index][end_index]
        max_sum = max(max_sum, current_sum)

    return max_sum

# 测试用例
