        current_sum = 0
        for j in range(k):
            start_index = i * n + min(j, n - 1)
            end_index = i * n + min(j + 1, n - 1)
            if start_index >= len(a): 
                break
            current_sum += dp[start_index][end_index]
        max_sum = max(max_sum, current_sum)

    return max_sum

