def remove_odd(s):
    # 检查字符串长度是否为偶数
    if len(s) % 2 == 0:
        return s

    # 将字符串转换为列表
    s_list = list(s)

    # 遍历列表并移除奇数索引的位置
    for i in range(len(s_list)):
        if i % 2 != 0:
            del s_list[i]

    # 如果列表为空，直接返回空字符串
    if not s_list:
        return ""

    # 将列表转换回字符串并返回
    return ''.join(s_list)

