def sumofFactors(n):
    # Check if n is odd
    if n % 2 != 0:
        return 0

    result = 0
    # Iterate from 2 to n//2
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            # Add both divisors if they are different
            if i * i == n:
                result += i
            else:
                result += i + n // i

    return result

