def combinations_list(lst):
    def helper(sub_lst, index):
        if index == len(lst):
            yield sub_lst
        else:
            # 不选择当前元素
            yield from helper(sub_lst, index + 1)

            # 选择当前元素
            new_sub_lst = sub_lst[:]
            new_sub_lst.append(lst[index])
            yield from helper(new_sub_lst, index + 1)

    return list(helper([], 0))

