import math

def perfect_squares(a, b):
    if a > b:
        a, b = (b, a)
    if b < 0:
        return []
    if a < 0:
        a = 0
    result = []
    for i in range(a, b + 1):
        root = int(math.sqrt(i))
        if root * root == i:
            result.append(i)
    return result

def binomial_Coefficient(n, k):
    if k > n:
        return 0
    elif k == 0 or k == n:
        return 1
    else:
        C = [[0] * (k+1) for _ in range(n+1)]
        C[0][0] = 1
        for i in range(1, n+1):
            for j in range(min(i, k)+1):
                if j == 0:
                    C[i][j] = 1
                else:
                    C[i][j] = C[i-1][j-1] + C[i-1][j]
        return C[n][k]

def sum_of_products(n):
    total_sum = 0
    for i in range(1, n+1):
        total_sum += binomial_Coefficient(2*i, i-1)
    return total_sum

