import re

def removezero_ip(ip):
    # 如果IP地址只有一个部分是0，则去掉多余的点和前导零
    if len(re.findall(r'[0]', ip)) == 1:
        parts = ip.split('.')
        for i in range(len(parts)):
            if parts[i] == '':
                parts[i] = '0'
        return '.'.join(parts)

    # 否则，使用正则表达式进行常规处理
    return re.sub(r'^((?:[1-9]\d*|0))\.(((?:[1-9]\d*|0))\.(((?:[1-9]\d*|0))\.(((?:[1-9]\d*|0))))$', 
                  r'\1.\2.\3.\4', ip)

