def find_kth(arr1, arr2, k):
    # Find the position of the k-th smallest number in arr1
    left = 0
    right = len(arr1) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr1[mid] >= k:
            right = mid - 1
        else:
            left = mid + 1

    # Determine which array contains the k-th smallest number
    if left == 0 or arr1[left - 1] != k:
        index = left
    elif left == len(arr1) or arr1[left] > k:
        index = left - 1
    else:
        index = left + 1

    # Use binary search on the other array to find the exact k-th smallest number
    left = 0
    right = len(arr2) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr2[mid] >= k:
            right = mid - 1
        else:
            left = mid + 1

    if left == 0 or arr2[left - 1] != k:
        index += 1
    elif left == len(arr2) or arr2[left] > k:
        index -= 1
    else:
        index += 1

    return arr2[index]

