def find_first_occurrence(A, x):
    left, right = (0, len(A) - 1)
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if x == A[mid]:
            result = mid
            right = mid - 1  # Move left pointer to mid-1 to ensure we get the first occurrence
        elif x < A[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return result

def sum_of_products(arr):
    def helper(start, end):
        if start > end:
            return 0
        else:
            # Calculate the product for this range and add it to the total
            return arr[start] * arr[end] + helper(start + 1, end - 1)

    n = len(arr)
    return helper(0, n - 1)

