def sum_of_products(arr):
    def helper(start, end):
        if start > end:
            return 0
        else:
            # Calculate the product for this range and add it to the total
            current_product = arr[start]
            for i in range(start + 1, end + 1):
                current_product *= arr[i]
            return current_product + helper(start + 1, end - 1)

    n = len(arr)
    return helper(0, n - 1)

