def divisible_by_digits(startnum, endnum):
    result = []
    for num in range(startnum, endnum + 1):
        # Check if the number is greater than or equal to 10 because leading zeros are not considered.
        if num >= 10:
            has_zero_digit = False
            for digit in str(num):
                if int(digit) == 0:
                    has_zero_digit = True
                    break
            if not has_zero_digit and all(int(digit) != 0 and num % int(digit) == 0 for digit in str(num)):
                result.append(num)
    return result

