import math

def is_polite(n):
    # Calculate the smallest positive integer that can be expressed as a sum of squares
    k = 1
    while True:
        if pow(k, 2) <= n:
            n -= pow(k, 2)
        else:
            break
        k += 1
    return n + 1

def find_nth_polite_number(n):
    count = 0
    num = 1
    while count < n:
        num += 1
        if is_polite(num) > 0:
            count += 1
    return num

# Test cases
print(find_nth_polite_number(7))  # Expected output: 11
print(find_nth_polite_number(4))  # Expected output: 7
print(find_nth_polite_number(9))  # Expected output: 13

