from collections import deque

def check_expression(exp):
    if len(exp) == 0 or len(exp) % 2 == 1:
        return False
    stack = deque()
    left_brackets = ['(', '[', '{']
    right_brackets = [')', ']', '}']

    for i, char in enumerate(exp):
        if char in left_brackets:
            stack.append((char, i))
        elif char in right_brackets:
            if not stack:
                return False
            current_char, _ = stack.pop()
            if left_brackets.index(current_char) != right_brackets.index(char):
                return False

    # Check if all left brackets have been matched with a right bracket
    while stack:
        _, index = stack.pop()
        if left_brackets[index] != char:
            return False

    return True

# Test cases
assert check_expression("{()}[{}]") == True
assert check_expression("{()}[{}") == False
assert check_expression("{()}[{}][]({})") == True

