import math

def count_divisors(n):
    cnt = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            # Check if both i and n/i are factors
            if n // i != i:
                cnt += 1
            else:
                cnt += 2
    return cnt % 2 == 0

def mul_even_odd(lst):
    if not lst:
        return -1

    first_even = next((el for el in lst if el % 2 == 0), -1)
    first_odd = next((el for el in lst if el % 1 != 0), -1)

    return first_even * first_odd

def tuple_str_int(test_str):
    # 使用 split 函数按逗号分割字符串，同时保留括号
    parts = test_str.split(',')
    result = []
    for part in parts:
        if '(' in part and ')' in part:
            # 如果部分包含括号，则跳过该部分
            continue
        try:
            result.append(int(part))
        except ValueError:
            raise ValueError(f"invalid literal for int() with base 10: '{part}'")

    return tuple(result)

# 测试用例
assert tuple_str_int("(7, 8, 9)") == (7, 8, 9)
assert tuple_str_int("(1, 2, 3)") == (1, 2, 3)
assert tuple_str_int("(4, 5, 6)") == (4, 5, 6)

import bisect

def right_insertion(a, x):
    # 使用 bisect_left 找到插入点
    index = bisect.bisect_left(a, x)
    # 如果插入点是列表的最后一个元素，说明 x 大于所有元素
    if index == len(a):
        return len(a)
    else:
        return index

# 测试用例
assert right_insertion([1, 2, 4, 5], 6) == 4
assert right_insertion([1, 2, 4, 5], 3) == 2
assert right_insertion([1, 2, 4, 5], 7) == 4

